import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u01")
C = "A2-B1"

L(1, "Já alguma vez…?", "Ben je ooit in Amsterdam geweest? Ik heb nog nooit…",
  ["Perguntar e falar de experiências de vida com ooit, al eens e nog nooit"],
  vocab=[V("v-al-eens","al eens","já (alguma vez)","expression",note="Heb je al eens sushi gegeten?"),
         V("v-ervaring","ervaring","experiência","noun","de","ervaringen")],
  ex=[("Ben je ooit in Amsterdam geweest?","Já alguma vez estiveste em Amesterdão?"),("Ik heb nog nooit gesurft.","Nunca fiz surf."),("Heb je al eens haring gegeten?","Já comeste arenque alguma vez?"),("Dat was een leuke ervaring.","Foi uma experiência gira.")],
  gram=[G("g-ervaringen","Falar de experiências: perfectum","Para experiências de vida usa-se o **perfectum** (hebben/zijn + particípio no fim). **ooit** e **al eens** = alguma vez; **nog nooit** = nunca (até hoje). Verbos de mudança de lugar ou estado usam **zijn**: *Ik ben in Japan geweest.*",
    [("Ik ben nog nooit in Japan geweest.","Nunca estive no Japão."),("Heb jij ooit een marathon gelopen?","Já alguma vez correste uma maratona?")],
    "Em português usamos o pretérito perfeito simples («estive»); em neerlandês, para experiências, usa-se o tempo composto.")],
  review=["v-nog-nooit","v-ooit","v-geweest","v-gegeten","v-gezien","v-nooit"],
  cefr=C, exs=[
    MA([("ooit","alguma vez"),("nog nooit","nunca (até agora)"),("ervaring","experiência"),("al eens","já alguma vez")], "Vocabulário de experiências.", ["v-ooit","v-nog-nooit","v-ervaring","v-al-eens"]),
    TR("pt-nl","Já alguma vez estiveste em Amesterdão?", ["Ben je ooit in Amsterdam geweest","Ben jij ooit in Amsterdam geweest","Ben je al eens in Amsterdam geweest"], "zijn + geweest; ooit depois do sujeito.", ["v-ooit","v-geweest"]),
    TR("nl-pt","Ik heb nog nooit haring gegeten.", ["Nunca comi arenque","Eu nunca comi arenque"], "nog nooit = nunca (até agora).", ["v-nog-nooit","v-gegeten"]),
    WO("Nunca estive no Japão.", ["Ik","ben","nog","nooit","in","Japan","geweest"], "Particípio no fim.", ["v-nog-nooit","v-geweest"]),
    FB("Heb je ___ eens een stroopwafel gegeten?", ["al"], "al eens = já alguma vez.", ["v-al-eens"], choices=["al","nog","ooit"], tr="Já comeste alguma vez uma stroopwafel?"),
    MC("Com «geweest» (estar), que auxiliar se usa?", ["*zijn","hebben|«Zijn» faz o perfectum com «zijn»: ik ben geweest.","worden|Não é auxiliar do perfectum."], "Ik ben geweest.", ["v-geweest"]),
    FE(["Ik","heb","nog","nooit","in","Parijs","geweest."], 1, "ben", "Com «geweest» usa-se zijn: ik ben … geweest.", ["v-geweest"]),
    AR("ervaring","a experiência","de", "Palavras em -ing são de-woorden.", ["v-ervaring"]),
    LI("Heb jij ooit een marathon gelopen?", ["Heb jij ooit een marathon gelopen","Heb je ooit een marathon gelopen"], "Já alguma vez correste uma maratona?", "ooit + perfectum.", ["v-ooit"]),
    DL([("Sanne","Ben je al eens in Maastricht geweest?","Já estiveste em Maastricht?"),("Rui","")], ["*Nee, nog nooit. Is het mooi?","Ja, ik ga morgen.|Responde com o futuro, não com uma experiência.","Ik heb Maastricht.|Não faz sentido."], "Responder sobre uma experiência.", ["v-nog-nooit"]),
  ], diff=3, mins=6)

L(2, "Particípios irregulares frequentes", "gezien, gedaan, gegeven, gevonden, gesproken…",
  ["Reconhecer e usar particípios irregulares muito frequentes"],
  vocab=[V("v-gedaan","gedaan","feito","verb",note="doen → gedaan"), V("v-gevonden","gevonden","encontrado","verb",note="vinden → gevonden"),
         V("v-gesproken","gesproken","falado","verb",note="spreken → gesproken"), V("v-gegeven","gegeven","dado","verb",note="geven → gegeven"),
         V("v-genomen","genomen","tirado|apanhado","verb",note="nemen → genomen")],
  ex=[("Wat heb je gisteren gedaan?","O que fizeste ontem?"),("Ik heb mijn sleutels gevonden.","Encontrei as minhas chaves."),("We hebben Nederlands gesproken.","Falámos neerlandês."),("Hij heeft de trein genomen.","Ele apanhou o comboio.")],
  gram=[G("g-part-irreg","Particípios irregulares","Muitos verbos fortes fazem o particípio com **ge- … -en** e mudam a vogal: *vinden → gevonden*, *spreken → gesproken*, *nemen → genomen*, *helpen → geholpen*. Outros mantêm a vogal: *geven → gegeven*, *lezen → gelezen*. Têm de se aprender de cor.",
    [("Ik heb haar geholpen.","Ajudei-a."),("Wie heeft dit boek geschreven?","Quem escreveu este livro?")])],
  review=["v-doen","v-vinden","v-spreken","v-geven","v-gelezen","v-geschreven"],
  cefr=C, exs=[
    MA([("doen","gedaan"),("vinden","gevonden"),("spreken","gesproken"),("nemen","genomen")], "Infinitivo e particípio.", ["v-gedaan","v-gevonden","v-gesproken","v-genomen"]),
    CJ("doen","jij","Wat heb je gisteren ___?", ["gedaan"], "doen → gedaan.", ["v-gedaan"], tense="passado-perfeito"),
    CJ("vinden","ik","Ik heb mijn sleutels ___.", ["gevonden"], "vinden → gevonden.", ["v-gevonden"], tense="passado-perfeito"),
    CJ("nemen","hij","Hij heeft de bus ___.", ["genomen"], "nemen → genomen.", ["v-genomen"], tense="passado-perfeito"),
    TR("pt-nl","Falámos neerlandês.", ["We hebben Nederlands gesproken","Wij hebben Nederlands gesproken"], "spreken → gesproken.", ["v-gesproken"]),
    TR("nl-pt","Ze heeft mij een cadeau gegeven.", ["Ela deu-me um presente","Ela ofereceu-me um presente"], "geven → gegeven.", ["v-gegeven"]),
    FE(["Ik","heb","het","boek","gevindt."], 4, "gevonden", "vinden é irregular: gevonden.", ["v-gevonden"]),
    MC("Qual é o particípio de «helpen»?", ["*geholpen","gehelpt|Helpen é irregular.","gehelpen|A vogal muda para «o»."], "helpen → geholpen.", []),
    LI("Wat hebben jullie in het weekend gedaan?", ["Wat hebben jullie in het weekend gedaan"], "O que fizeram no fim de semana?", "gedaan.", ["v-gedaan"]),
    BS("Ele apanhou o comboio das oito.", ["Hij","heeft","de","trein","van","acht","uur","genomen","gegeven"], ["Hij heeft de trein van acht uur genomen"], "nemen → genomen; «gegeven» sobra.", ["v-genomen"]),
  ], diff=3, mins=7)

L(3, "Onde estiveste nas férias?", "Contar uma viagem: we zijn naar … gegaan, we hebben … bezocht.",
  ["Contar uma viagem no passado com zijn e hebben"],
  vocab=[V("v-bezocht","bezocht","visitado","verb",note="bezoeken → bezocht"), V("v-gevlogen","gevlogen","voado","verb",note="vliegen → (zijn) gevlogen"),
         V("v-gereisd","gereisd","viajado","verb",note="reizen → (hebben/zijn) gereisd"), V("v-uitzicht","uitzicht","vista","noun","het")],
  ex=[("We zijn naar Italië gevlogen.","Fomos de avião para Itália."),("We hebben Rome bezocht.","Visitámos Roma."),("Het uitzicht was prachtig.","A vista era magnífica."),("Ik heb veel gereisd.","Viajei muito.")],
  gram=[G("g-zijn-hebben-beweging","Zijn ou hebben com movimento","Com destino expresso (*naar …*) os verbos de movimento usam **zijn**: *We zijn naar Spanje gevlogen.* Sem destino, só a atividade, usa-se **hebben**: *We hebben veel gefietst.* Verbos sem movimento usam **hebben**: *We hebben Rome bezocht.*",
    [("Ik ben naar huis gefietst.","Fui para casa de bicicleta."),("Ik heb twee uur gefietst.","Andei duas horas de bicicleta.")],
    "Em português o auxiliar não muda; aqui é a ideia de deslocação até um destino que pede «zijn».")],
  review=["v-vakantie","v-gegaan","v-vliegveld","v-strand"],
  cefr=C, exs=[
    MA([("bezocht","visitado"),("gevlogen","voado"),("uitzicht","vista"),("gereisd","viajado")], "Viagens no passado.", ["v-bezocht","v-gevlogen","v-uitzicht","v-gereisd"]),
    FB("We ___ naar Italië gevlogen.", ["zijn"], "Destino expresso → zijn.", ["v-gevlogen"], choices=["zijn","hebben","worden"], tr="Fomos de avião para Itália."),
    FB("We ___ het museum bezocht.", ["hebben"], "bezoeken → hebben.", ["v-bezocht"], choices=["hebben","zijn","waren"], tr="Visitámos o museu."),
    TR("pt-nl","Visitámos Roma.", ["We hebben Rome bezocht","Wij hebben Rome bezocht"], "bezoeken → bezocht.", ["v-bezocht"]),
    TR("nl-pt","Het uitzicht was prachtig.", ["A vista era [magnífica|linda|lindíssima]","A vista foi [magnífica|linda]"], "het uitzicht.", ["v-uitzicht"]),
    AR("uitzicht","a vista","het", "Het uitzicht.", ["v-uitzicht"]),
    WO("Fui para casa de bicicleta.", ["Ik","ben","naar","huis","gefietst"], "Destino → zijn.", []),
    FE(["Wij","hebben","naar","Spanje","gevlogen."], 1, "zijn", "Com destino (naar Spanje) usa-se zijn.", ["v-gevlogen"]),
    CO("text","Vakantie in Portugal", "Vorig jaar zijn Tom en Lisa naar Portugal gevlogen. Ze hebben eerst een week in Lissabon gelogeerd en daarna zijn ze met de auto naar de Algarve gereden. Het uitzicht over de zee was prachtig, maar het was erg warm.",
       [("Como foram para Portugal?", ["*De avião","De comboio","De carro"]),("O que acharam do tempo?", ["*Muito quente","Muito frio","Chuvoso"])],
       "gevlogen = de avião; warm = quente.", ["v-gevlogen","v-uitzicht"]),
    SW("Escreva 2–3 frases sobre uma viagem que fez (para onde foi, o que visitou).", ["Ik ben naar Spanje gegaan. Ik heb Barcelona bezocht. Het was heel mooi."], ["Usou **zijn** com destino (naar …)", "Usou **hebben** com bezocht/gezien", "Particípio no fim da frase"], 10, "Perfectum para contar uma viagem.", ["v-bezocht"]),
  ], diff=3, mins=7)

L(4, "Desde quando? Há quanto tempo?", "Ik woon hier sinds 2020. Ik heb hem twee jaar geleden ontmoet.",
  ["Situar experiências no tempo com geleden, sinds e al … lang"],
  vocab=[V("v-ontmoet","ontmoet","conhecido (pessoa)","verb",note="ontmoeten → ontmoet (sem ge-)"),
         V("v-verhuisd","verhuisd","mudado (de casa)","verb",note="verhuizen → (zijn) verhuisd"), V("v-al-lang","al lang","há muito tempo (e continua)","expression")],
  ex=[("Ik heb hem twee jaar geleden ontmoet.","Conheci-o há dois anos."),("We zijn in 2021 verhuisd.","Mudámo-nos em 2021."),("Ik woon hier al lang.","Moro aqui há muito tempo."),("Hoe lang geleden was dat?","Há quanto tempo foi isso?")],
  gram=[G("g-geleden-sinds","Geleden vs. sinds","**… geleden** marca um momento terminado no passado (com perfectum ou imperfectum): *drie jaar geleden*. Para algo que começou e **continua**, usa-se o **presente** com **al** ou **sinds**: *Ik woon hier al drie jaar* / *sinds 2021*.",
    [("Ik ben drie jaar geleden verhuisd.","Mudei-me há três anos."),("Ik woon hier al drie jaar.","Moro aqui há três anos.")],
    "Em português «há três anos» serve para as duas coisas; em neerlandês distingue-se.")],
  review=["v-geleden","v-sinds","v-al","v-jaar","v-verhuizen"],
  cefr=C, exs=[
    MA([("geleden","há (tempo atrás)"),("ontmoet","conhecido"),("verhuisd","mudado de casa"),("al lang","há muito tempo")], "Tempo.", ["v-geleden","v-ontmoet","v-verhuisd","v-al-lang"]),
    TR("pt-nl","Conheci-o há dois anos.", ["Ik heb hem twee jaar geleden ontmoet"], "… geleden + perfectum.", ["v-geleden","v-ontmoet"]),
    TR("pt-nl","Moro aqui há três anos.", ["Ik woon hier al drie jaar","Ik woon hier sinds drie jaar"], "Continua → presente + al.", ["v-al-lang"]),
    MC("«Moro em Utrecht há cinco anos» (e continuo):", ["*Ik woon al vijf jaar in Utrecht.","Ik heb vijf jaar geleden in Utrecht gewoond.|Isso sugere que já não mora lá.","Ik woonde vijf jaar geleden.|Não está completo."], "Presente + al.", ["v-al-lang"]),
    FB("We zijn drie jaar ___ naar Nederland verhuisd.", ["geleden"], "Momento terminado.", ["v-geleden"], choices=["geleden","sinds","al"], tr="Mudámo-nos para os Países Baixos há três anos."),
    MC("Qual é o particípio de «ontmoeten»?", ["*ontmoet","geontmoet|Verbos com ont- não levam ge-.","ontmoeten|Esse é o infinitivo."], "ont- → sem ge-.", ["v-ontmoet"]),
    FE(["We","hebben","vorig","jaar","verhuisd."], 1, "zijn", "verhuizen usa zijn: we zijn verhuisd.", ["v-verhuisd"]),
    LI("Hoe lang geleden was dat?", ["Hoe lang geleden was dat"], "Há quanto tempo foi isso?", "geleden.", ["v-geleden"]),
    DL([("Collega","Hoe lang woon je al in Nederland?","Há quanto tempo vives nos Países Baixos?"),("Inês","")], ["*Ik woon hier al vier jaar.","Ik woon hier vier jaar geleden.|«geleden» não serve para algo que continua.","Ik ben vier jaar.|Isso seria a idade."], "al + duração.", ["v-al-lang"]),
    WO("Mudámo-nos em 2021.", ["We","zijn","in","2021","verhuisd"], "zijn + verhuisd.", ["v-verhuisd"]),
  ], diff=3, mins=6)

L(5, "Prática: a minha história", "Juntar tudo: experiências, viagens e datas.",
  ["Contar a própria história com o perfectum"],
  vocab=[V("v-geboren","geboren","nascido","adjective",note="Ik ben geboren in Porto."), V("v-opgegroeid","opgegroeid","crescido (criado)","verb",note="opgroeien → (zijn) opgegroeid"),
         V("v-gestudeerd","gestudeerd","estudado","verb"), V("v-begonnen","begonnen","começado","verb",note="beginnen → (zijn) begonnen")],
  ex=[("Ik ben in Porto geboren.","Nasci no Porto."),("Ik ben in Braga opgegroeid.","Cresci em Braga."),("Ik heb in Lissabon gestudeerd.","Estudei em Lisboa."),("Ik ben vorig jaar met Nederlands begonnen.","Comecei o neerlandês no ano passado.")],
  review=["v-geleden","v-verhuisd","v-ooit","v-ervaring"],
  cefr=C, exs=[
    MA([("geboren","nascido"),("opgegroeid","crescido"),("gestudeerd","estudado"),("begonnen","começado")], "A minha história.", ["v-geboren","v-opgegroeid","v-gestudeerd","v-begonnen"]),
    TR("pt-nl","Nasci no Porto.", ["Ik ben in Porto geboren","Ik ben geboren in Porto"], "Ik ben … geboren.", ["v-geboren"]),
    TR("nl-pt","Ik ben in Braga opgegroeid.", ["Cresci em Braga","Eu cresci em Braga","Fui criado em Braga"], "opgroeien → opgegroeid.", ["v-opgegroeid"]),
    FB("Ik ___ vorig jaar met Nederlands begonnen.", ["ben"], "beginnen → zijn.", ["v-begonnen"], choices=["ben","heb","word"], tr="Comecei o neerlandês no ano passado."),
    CJ("studeren","ik","Ik heb in Coimbra ___.", ["gestudeerd"], "Regular: ge- + stam + d.", ["v-gestudeerd"], tense="passado-perfeito"),
    FE(["Ik","heb","in","Lissabon","geboren."], 1, "ben", "Ik ben geboren.", ["v-geboren"]),
    CO("text","Mijn verhaal", "Ik heet Marta. Ik ben in 1995 in Faro geboren en ik ben daar ook opgegroeid. Ik heb in Lissabon gestudeerd. Vijf jaar geleden ben ik naar Rotterdam verhuisd voor mijn werk. Ik heb nog nooit zo veel fietsen gezien!",
       [("Onde estudou a Marta?", ["*Em Lisboa","Em Faro","Em Roterdão"]),("Quando se mudou para Roterdão?", ["*Há cinco anos","Em 1995","No ano passado"])],
       "vijf jaar geleden = há cinco anos.", ["v-geboren","v-gestudeerd","v-geleden"]),
    WO("Estudei em Lisboa.", ["Ik","heb","in","Lissabon","gestudeerd"], "Particípio no fim.", ["v-gestudeerd"]),
    LI("Waar ben je opgegroeid?", ["Waar ben je opgegroeid","Waar ben jij opgegroeid"], "Onde cresceste?", "opgegroeid.", ["v-opgegroeid"]),
    SW("Apresente a sua história em 3–4 frases: onde nasceu, onde cresceu, o que estudou e quando começou o neerlandês.", ["Ik ben in Porto geboren en ik ben daar opgegroeid. Ik heb in Lissabon gestudeerd. Vorig jaar ben ik met Nederlands begonnen."], ["**Ik ben … geboren**", "Usou **zijn** com opgegroeid/begonnen/verhuisd", "Usou **hebben** com gestudeerd", "Particípio no fim"], 15, "Perfectum na biografia.", ["v-geboren","v-opgegroeid","v-gestudeerd","v-begonnen"]),
  ], diff=3, mins=8)

W()
